export function M6_QUESTIONS(){return[
  {type:'mc',era:'Medieval',q:'Who hosted the Synod of Whitby at her double monastery?',correct:'Abbess Hilda',wrong:['Abbess Etheldreda','Abbess Brigid','Queen Bertha','Queen Eanflæd','Abbess Mildred','Abbess Werburgh','Empress Theodora'],explain:'Hilda, abbess of the double monastery at Whitby, hosted the 664 synod.'},
  {type:'mc',era:'Medieval',q:'Which king of Northumbria delivered the synod\'s verdict?',correct:'Oswiu',wrong:['Egbert','Edwin','Alfred','Ethelbert','Athelstan','Edgar','Penda'],explain:'Oswiu of Northumbria heard both sides at Whitby and ruled in favor of Roman practice.'},
  {type:'mc',era:'Medieval',q:'What two practices was the Synod of Whitby called to settle?',correct:'The date of Easter and the shape of the tonsure',wrong:['The number of sacraments and infant baptism','The veneration of icons and relics','The role of bishops and the office of pope','The seven liberal arts and the trivium','Clerical celibacy and clerical poverty','The use of Latin and vernacular liturgy','The keeping of fasts and the saying of the Office'],explain:'The Roman and Celtic missions used different reckonings for Easter and shaved their hair in different patterns.'},
  {type:'mc',era:'Medieval',q:'In whose favor did Oswiu rule at Whitby?',correct:'The Roman practice',wrong:['The Celtic practice','The Byzantine practice','The Frankish practice','A compromise between Roman and Celtic','The Iona practice','A new Northumbrian practice'],explain:'Oswiu\'s decision anchored English Christianity to the wider Latin church.'},
  {type:'tf',era:'Medieval',q:'Oswiu cited Peter\'s authority — the keeper of the keys of heaven — as his reason for siding with Rome.',answer:true,explain:'Oswiu said he would not contradict the doorkeeper of the kingdom — Peter, whose authority Rome claimed.'},
  {type:'mc',era:'Medieval',q:'The Celtic mission to Northumbria had been planted from which island monastery?',correct:'Iona',wrong:['Whitby','Lindisfarne','Canterbury','Jarrow','Bobbio','Mont-Saint-Michel'],explain:'Iona, founded by Columba, sent Aidan to plant the Celtic mission at Lindisfarne in 635.'},
  {type:'mc',era:'Medieval',q:'Which Northumbrian tidal-island monastery served as the Celtic mission\'s English base?',correct:'Lindisfarne',wrong:['Iona','Whitby','Jarrow','Canterbury','Wearmouth','York'],explain:'Aidan founded the Celtic mission at Lindisfarne in 635, on the Northumbrian coast.'},
  {type:'mc',era:'Medieval',q:'Whitby is remembered as a parable of what?',correct:'The church debating secondary issues while losing its mission lands',wrong:['The triumph of Celtic Christianity over Rome','The unity of the Eastern and Western churches','The defeat of Islam at the western frontier','The first great monastic reform','The end of barbarian invasions','The rise of the papacy over the emperor','The conversion of the Slavs'],explain:'In the very years Whitby debated Easter and tonsures, Islam was sweeping the Christian heartlands of the Near East and North Africa.'},
  {type:'mc',era:'Medieval',q:'In what year did the Synod of Whitby meet?',correct:'664',wrong:['597','622','680','732','787','635'],explain:'The Synod of Whitby was convened in 664 to settle the Easter dispute in England.'},
  {type:'quote',era:'Medieval',quote:'"I will not contradict the keeper of the keys of heaven."',cite:'— A king\'s reasoning at the Synod of Whitby',q:'Who spoke this verdict, choosing Rome over the Celtic party?',correct:'Oswiu of Northumbria',wrong:['Abbess Hilda','Augustine of Canterbury','Wilfrid of Ripon','Colmán of Lindisfarne','Aidan of Iona','Gregory the Great'],explain:'King Oswiu said he would not contradict Peter, the keeper of the keys, and ruled for Roman practice.'},
  {type:'mc',era:'Medieval',q:'Which apostle\'s authority did Oswiu cite as decisive at Whitby?',correct:'Peter',wrong:['Paul','John','Andrew','James','Thomas','Matthew'],explain:'Oswiu said Peter holds the keys of the kingdom — he would not contradict the doorkeeper.'},
  {type:'mc',era:'Medieval',q:'What chief feast-date dispute did Whitby settle?',correct:'Easter',wrong:['Christmas','Pentecost','Epiphany','Advent','Lent','All Saints'],explain:'Roman and Celtic Christians used different reckonings for Easter — sometimes weeks apart.'},
  {type:'timeline',era:'Medieval',q:'Put these milestones of the English missions in order.',events:[{label:'Augustine plants the Roman mission at Canterbury',year:597},{label:'Aidan founds the Celtic mission at Lindisfarne',year:635},{label:'Synod of Whitby',year:664}],explain:'The arc runs from the Roman mission at Canterbury (597) through the Celtic mission at Lindisfarne (635) to the synod that settled them (664).'},
]}

export function M7_QUESTIONS(){return[
  {type:'mc',era:'Medieval',q:'What name does the 8th-century struggle over sacred images go by?',correct:'Iconoclastic Controversy',wrong:['Filioque Controversy','Investiture Controversy','Monophysite Controversy','Donatist Controversy','Arian Controversy','Photian Schism','Three Chapters Controversy'],explain:'The Iconoclastic Controversy was the century-long struggle in the Byzantine East over whether the Christian use of icons violated the second commandment.'},
  {type:'mc',era:'Medieval',q:'Which Byzantine emperor launched the iconoclast policy by ordering the removal of an icon of Christ from the palace gate?',correct:'Leo III',wrong:['Justinian I','Constantine V','Constantine VI','Heraclius','Basil I','Michael III','Leo VI'],explain:'In 726 the emperor Leo III ordered the removal of an icon of Christ from the palace gate — the opening act of the Iconoclastic Controversy.'},
  {type:'mc',era:'Medieval',q:'In what year did Leo III order the removal of icons from the imperial palace?',correct:'726',wrong:['717','754','780','787','843','680','711'],explain:'Leo III\'s order in 726 launched the iconoclast policy in the Byzantine East.'},
  {type:'mc',era:'Medieval',q:'What name was given to those who opposed the use of sacred images and broke them down?',correct:'Iconoclasts',wrong:['Iconodules','Monophysites','Nestorians','Filioquists','Donatists','Arians','Pelagians'],explain:'"Iconoclasts" — literally "image-breakers" — were those who held that icons of Christ and the saints violated the second commandment.'},
  {type:'mc',era:'Medieval',q:'From what doctrine did the defenders of the icons draw their strongest argument?',correct:'The Incarnation',wrong:['The Trinity','The Atonement','Original sin','The Resurrection','Predestination','Sola scriptura','Apostolic succession'],explain:'Defenders of the icons argued from the Incarnation: because the eternal Son took flesh, his flesh — and so his image — could rightly be honored.'},
  {type:'mc',era:'Medieval',q:'Which monk became the chief defender of the icons, writing from a monastery beyond the reach of the Byzantine emperor under Muslim rule?',correct:'John of Damascus',wrong:['Maximus the Confessor','Theodore the Studite','Gregory the Great','Photios','Cyril of Alexandria','Athanasius','Basil the Great'],explain:'John of Damascus, a monk under Muslim rule in Syria and out of the emperor\'s reach, became the great theological defender of the icons.'},
  {type:'mc',era:'Medieval',q:'In what work did John of Damascus defend the use of icons?',correct:'Three Apologetic Treatises',wrong:['Cur Deus Homo','The City of God','The Sentences','Summa Theologica','On the Trinity','The Holy Rule','Mystagogia'],explain:'John of Damascus\'s Three Apologetic Treatises Against Those Who Decry the Holy Images set out the iconodule case during the controversy.'},
  {type:'tf',era:'Medieval',q:'John of Damascus distinguished between latreia (worship, due to God alone) and proskynesis (veneration, which may be given to icons and saints).',answer:true,explain:'John of Damascus\'s decisive distinction held that only God receives latreia (worship), while icons and saints receive proskynesis (veneration).'},
  {type:'mc',era:'Medieval',q:'What Greek term names the worship that belongs to God alone?',correct:'Latreia',wrong:['Proskynesis','Doxa','Eucharistia','Anamnesis','Kenosis','Theosis','Logos'],explain:'Latreia is the worship due to God alone, distinct from the proskynesis (veneration) given to icons and saints.'},
  {type:'mc',era:'Medieval',q:'What Greek term names the veneration that may rightly be given to icons and saints?',correct:'Proskynesis',wrong:['Latreia','Doxa','Eucharistia','Kenosis','Anamnesis','Theosis','Logos'],explain:'Proskynesis is veneration — bowing or honoring — distinct from the latreia (worship) due only to God.'},
  {type:'mc',era:'Medieval',q:'Which empress summoned the council that restored the veneration of icons?',correct:'Irene',wrong:['Theodora','Pulcheria','Eudoxia','Helena','Sophia','Anna','Athenais'],explain:'The Empress Irene summoned the Second Council of Nicaea in 787, which restored the icons after sixty years of conflict.'},
  {type:'mc',era:'Medieval',q:'At what 787 council was the Iconoclastic Controversy settled in favor of the icons?',correct:'Second Council of Nicaea',wrong:['First Council of Nicaea','Council of Chalcedon','Council of Ephesus','Council of Constantinople','Council of Hieria','Synod of Whitby','Lateran I'],explain:'The Second Council of Nicaea (787) — the seventh ecumenical council — restored icon veneration and ended the first phase of the controversy.'},
  {type:'mc',era:'Medieval',q:'In what year was the Second Council of Nicaea — the seventh ecumenical council — held?',correct:'787',wrong:['680','726','843'],explain:'The Second Council of Nicaea (787) restored icon veneration and is the seventh and final ecumenical council recognized by both East and West.'},
  {type:'timeline',era:'Medieval',q:'Put these events of the Iconoclastic Controversy in order.',events:[{label:'Leo III orders the removal of icons',year:726},{label:'John of Damascus dies, after defending the icons',year:749},{label:'Second Council of Nicaea restores icon veneration',year:787}],explain:'The controversy ran from Leo III\'s 726 order through John of Damascus\'s defense to its resolution at Nicaea II in 787.'},
]}

