export function M31_QUESTIONS(){return[
  {type:'mc',era:'Medieval',q:'What name was given to the 7th-century doctrine that Christ had only one will?',correct:'Monothelitism',wrong:['Monophysitism','Nestorianism','Iconoclasm','Pelagianism','Donatism','Arianism','Monoenergism'],explain:'Monothelitism — from the Greek for "one will" — held that the incarnate Christ had a single, divine will.'},
  {type:'mc',era:'Medieval',q:'How many wills did Maximus the Confessor insist that Christ possesses?',correct:'Two',wrong:['One','Three','None','Four'],explain:'Maximus defended dyothelitism: Christ has two wills, divine and human, answering to his two natures.'},
  {type:'mc',era:'Medieval',q:'In Maximus’s theology, the two wills of Christ correspond to his two _____.',correct:'Natures',wrong:['Persons','Energies','Names','Bodies','Titles','Minds','Spirits'],explain:'Two natures (divine and human), defined at Chalcedon, imply two wills — the human will freely submitting to the divine.'},
  {type:'mc',era:'Medieval',q:'Which Byzantine emperor promoted the one-will teaching as a compromise to win back the Monophysites?',correct:'Heraclius',wrong:['Justinian I','Constantine V','Leo III','Constantine the Great','Basil I','Maurice','Phocas'],explain:'Heraclius backed Monothelitism to reconcile the Monophysite provinces, proclaiming one will in his Ecthesis of 638.'},
  {type:'mc',era:'Medieval',q:'In 638 Heraclius proclaimed the one-will doctrine in an imperial decree called the _____.',correct:'Ecthesis',wrong:['Typos','Henotikon','Tome of Leo','Edict of Milan','Filioque','Henoticon of Zeno','Dialogus'],explain:'The Ecthesis (638) was Heraclius’s decree affirming a single will in Christ.'},
  {type:'mc',era:'Medieval',q:'What was the name of Emperor Constans II’s 648 edict forbidding all debate over Christ’s wills?',correct:'Typos',wrong:['Ecthesis','Henotikon','Tome','Interdict','Pragmatic Sanction','Donation','Capitulary'],explain:'The Typos (648) of Constans II banned discussion of one or two wills — the silence Maximus refused to keep.'},
  {type:'mc',era:'Medieval',q:'Alongside Maximus, which pope condemned Monothelitism at the Lateran Synod of 649?',correct:'Martin I',wrong:['Gregory the Great','Leo III','Nicholas I','Gregory VII','Vigilius','Honorius I','Stephen II'],explain:'Pope Martin I joined Maximus in condemning the one-will teaching at the Lateran Synod of 649 — and was himself arrested for it.'},
  {type:'mc',era:'Medieval',q:'At which 649 Roman synod was Monothelitism condemned?',correct:'Lateran Synod',wrong:['Synod of Whitby','Second Council of Nicaea','Council of Chalcedon','Council of Hieria','Lateran Council of 1215','Council of Ephesus','Synod of Hiereia'],explain:'The Lateran Synod of 649, under Pope Martin I and shaped by Maximus, condemned the one-will doctrine.'},
  {type:'mc',era:'Medieval',q:'How did Maximus’s persecutors try to silence his defense of two wills?',correct:'Cut out his tongue and right hand',wrong:['Burned him at the stake','Drowned him in the Bosphorus','Blinded both his eyes','Crucified him','Stoned him outside the walls','Starved him in prison','Sold him into slavery'],explain:'To stop him speaking and writing, they cut out his tongue and cut off his right hand; he died in exile in 662 — hence "the Confessor."'},
  {type:'mc',era:'Medieval',q:'In what year did Maximus the Confessor die in exile?',correct:'662',wrong:['638','649','681','604','726','787','610'],explain:'Maximus died in exile in 662, his tongue and right hand cut off for refusing the emperor’s formula.'},
  {type:'mc',era:'Medieval',q:'Which ecumenical council, in 680–681, vindicated Maximus by condemning Monothelitism?',correct:'Third Council of Constantinople',wrong:['Second Council of Nicaea','Council of Chalcedon','Second Council of Constantinople','Council of Ephesus','First Council of Nicaea','Lateran Synod','Council of Hieria'],explain:'The Third Council of Constantinople (680–681), the sixth ecumenical council, affirmed two wills in Christ — vindicating Maximus nearly twenty years after his death.'},
  {type:'quote',era:'Medieval',quote:'"Even if the whole world should enter into communion with the patriarch, I will not."',cite:'— attributed to Maximus the Confessor',q:'Who refused communion with the imperial church over the one-will doctrine?',correct:'Maximus the Confessor',wrong:['John of Damascus','Pope Martin I','Athanasius','Theodore the Studite','Gregory the Great','Cyril of Alexandria','Photios'],explain:'Pressed to accept the imperial formula even though emperor and patriarchs had embraced it, Maximus stood almost alone.'},
  {type:'timeline',era:'Medieval',q:'Put these events of the Monothelite controversy in order.',events:[{label:'Heraclius proclaims one will in the Ecthesis',year:638},{label:'The Lateran Synod condemns Monothelitism',year:649},{label:'Maximus dies in exile, mutilated',year:662},{label:'Third Council of Constantinople affirms two wills',year:681}],explain:'From the Ecthesis (638) through the Lateran Synod (649) and Maximus’s death (662) to his vindication at Constantinople III (681).'},
]}

